import type { LocationQuery, LocationQueryRaw } from 'vue-router'
import type { TransactionRange } from '@/domain/services/date-range'

export type TransactionDimension = 'time' | 'category'
export type CategoryGroupLevel = 'parent' | 'child'

export interface TransactionView {
  dimension: TransactionDimension
  range: TransactionRange
  categoryLevel: CategoryGroupLevel
  focusCategoryId?: string
  focusType?: 'income' | 'expense'
}

const RANGES: readonly TransactionRange[] = ['day', 'week', 'month', 'year']

function firstValue(value: LocationQuery[string]): string | undefined {
  const single = Array.isArray(value) ? value[0] : value
  return single ?? undefined
}

/**
 * 从地址栏查询参数解析流水页视图。非法值一律回退到安全默认
 * （时间维度 / 月 / 一级分类），focus/type 只在分类维度下保留（报表跳转入口）。
 */
export function readTransactionView(query: LocationQuery): TransactionView {
  const rawRange = firstValue(query.range)
  const range: TransactionRange = RANGES.includes(rawRange as TransactionRange) ? rawRange as TransactionRange : 'month'
  const dimension: TransactionDimension = firstValue(query.dimension) === 'category' ? 'category' : 'time'
  const categoryLevel: CategoryGroupLevel = firstValue(query.level) === 'child' ? 'child' : 'parent'
  const view: TransactionView = { dimension, range, categoryLevel }
  if (dimension === 'category') {
    const focus = firstValue(query.focus)
    const type = firstValue(query.type)
    if (focus) {
      view.focusCategoryId = focus
      if (type === 'income' || type === 'expense') view.focusType = type
    }
  }
  return view
}

/** 视图 → 地址栏查询参数。时间维度沿用旧版 range 参数；focus/type 随分类维度序列化。 */
export function transactionViewQuery(view: TransactionView): LocationQueryRaw {
  if (view.dimension === 'category') {
    return {
      dimension: 'category',
      level: view.categoryLevel,
      ...(view.focusCategoryId ? { focus: view.focusCategoryId } : {}),
      ...(view.focusCategoryId && view.focusType ? { type: view.focusType } : {}),
    }
  }
  return { range: view.range }
}
