<script setup lang="ts">
import { ref, watch } from 'vue'
import { Check, ChevronLeft, ChevronRight } from '@lucide/vue'
import AppDialog from '@/components/AppDialog.vue'
import type { TransactionRange } from '@/domain/services/date-range'
import type { CategoryGroupLevel, TransactionView } from './transaction-view'

const props = defineProps<{ open: boolean; view: TransactionView }>()
const emit = defineEmits<{
  close: []
  selectTime: [range: TransactionRange]
  selectCategory: [level: CategoryGroupLevel]
}>()

type Step = 'root' | 'time' | 'category'
const step = ref<Step>('root')
watch(() => props.open, (open) => { if (open) step.value = 'root' })

const timeOptions: readonly { value: TransactionRange; label: string }[] = [
  { value: 'day', label: '天' },
  { value: 'week', label: '周' },
  { value: 'month', label: '月' },
  { value: 'year', label: '年' },
]
const categoryOptions: readonly { value: CategoryGroupLevel; label: string }[] = [
  { value: 'parent', label: '一级分类' },
  { value: 'child', label: '二级分类' },
]

function currentLabel(stepName: 'time' | 'category'): string {
  if (stepName === 'time') return timeOptions.find((option) => option.value === props.view.range)?.label ?? ''
  return categoryOptions.find((option) => option.value === props.view.categoryLevel)?.label ?? ''
}

function chooseTime(range: TransactionRange): void {
  emit('selectTime', range)
  emit('close')
}

function chooseCategory(level: CategoryGroupLevel): void {
  emit('selectCategory', level)
  emit('close')
}
</script>

<template>
  <AppDialog :open="open" title="筛选流水" position="bottom" @close="emit('close')">
    <div v-if="step === 'root'" class="filter-roots">
      <button class="filter-root" type="button" :aria-label="`时间，当前：${currentLabel('time')}`" @click="step = 'time'">
        <span>时间</span>
        <span class="filter-root-value">{{ currentLabel('time') }}<ChevronRight :size="18" aria-hidden="true" /></span>
      </button>
      <button class="filter-root" type="button" :aria-label="`分类，当前：${currentLabel('category')}`" @click="step = 'category'">
        <span>分类</span>
        <span class="filter-root-value">{{ currentLabel('category') }}<ChevronRight :size="18" aria-hidden="true" /></span>
      </button>
    </div>

    <div v-else class="filter-leaves">
      <button class="filter-back" type="button" aria-label="返回筛选方式" @click="step = 'root'">
        <ChevronLeft :size="20" aria-hidden="true" /><span>{{ step === 'time' ? '时间' : '分类' }}</span>
      </button>
      <div v-if="step === 'time'" role="menu" aria-label="时间分组">
        <button
          v-for="option in timeOptions"
          :key="option.value"
          class="filter-leaf"
          type="button"
          role="menuitemradio"
          :aria-checked="view.dimension === 'time' && view.range === option.value"
          @click="chooseTime(option.value)"
        >
          <span>{{ option.label }}</span>
          <Check v-if="view.dimension === 'time' && view.range === option.value" :size="18" aria-hidden="true" />
        </button>
      </div>
      <div v-else role="menu" aria-label="分类分组">
        <button
          v-for="option in categoryOptions"
          :key="option.value"
          class="filter-leaf"
          type="button"
          role="menuitemradio"
          :aria-checked="view.dimension === 'category' && view.categoryLevel === option.value"
          @click="chooseCategory(option.value)"
        >
          <span>{{ option.label }}</span>
          <Check v-if="view.dimension === 'category' && view.categoryLevel === option.value" :size="18" aria-hidden="true" />
        </button>
      </div>
    </div>
  </AppDialog>
</template>

<style scoped>
.filter-roots { display: flex; flex-direction: column; }
.filter-root { display: flex; min-height: 54px; align-items: center; justify-content: space-between; padding: 0 4px; border: 0; border-bottom: 1px solid var(--color-border); background: transparent; color: var(--color-text); font-size: 16px; font-weight: 600; }
.filter-root:last-child { border-bottom: 0; }
.filter-root:active { background: var(--color-surface-muted); }
.filter-root-value { display: inline-flex; align-items: center; gap: 2px; color: var(--color-text-secondary); font-size: 14px; font-weight: 500; }
.filter-back { display: inline-flex; min-height: 44px; align-items: center; gap: 2px; margin-bottom: 4px; padding: 0 8px 0 0; border: 0; background: transparent; color: var(--color-primary); font-size: 15px; font-weight: 700; }
.filter-leaf { display: flex; width: 100%; min-height: 52px; align-items: center; justify-content: space-between; padding: 0 4px; border: 0; border-bottom: 1px solid var(--color-border); background: transparent; color: var(--color-text); font-size: 16px; }
.filter-leaf:last-child { border-bottom: 0; }
.filter-leaf:active { background: var(--color-surface-muted); }
.filter-leaf[aria-checked='true'] { color: var(--color-primary); font-weight: 700; }
</style>
